package com.udhaardaar.mvp

import android.app.AlertDialog
import android.content.Intent
import android.graphics.Color
import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.view.Gravity
import android.view.View
import android.view.WindowManager
import android.widget.*
import androidx.appcompat.app.AppCompatActivity

class V5HomeActivity : AppCompatActivity() {
 private val prefs by lazy { getSharedPreferences("udhaardaar_accounts", MODE_PRIVATE) }
 private val bg=Color.rgb(246,249,252);private val blue=Color.rgb(25,111,220);private val teal=Color.rgb(0,145,135);private val navy=Color.rgb(24,58,92);private val green=Color.rgb(25,145,78);private val amber=Color.rgb(210,135,15);private val red=Color.rgb(190,55,55)
 private fun dp(x:Int)=(x*resources.displayMetrics.density).toInt()
 private fun card(c:Int=Color.WHITE,s:Int=Color.rgb(205,215,225))=GradientDrawable().apply{setColor(c);setStroke(dp(1),s);cornerRadius=dp(16).toFloat()}
 private fun tv(s:String,z:Float=16f,c:Int=navy)=TextView(this).apply{text=s;textSize=z;setTextColor(c);setPadding(dp(5),dp(5),dp(5),dp(5))}
 private fun root()=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),dp(12),dp(16),dp(92));setBackgroundColor(bg)}
 private fun put(r:LinearLayout,v:View,h:Int=52){r.addView(v,LinearLayout.LayoutParams(-1,dp(h)).apply{setMargins(0,dp(4),0,dp(4))})}
 private fun show(r:LinearLayout){val frame=FrameLayout(this);frame.addView(ScrollView(this).apply{isFillViewport=true;isSmoothScrollingEnabled=true;addView(r)},FrameLayout.LayoutParams(-1,-1));frame.addView(bottomNav(),FrameLayout.LayoutParams(-1,dp(72),Gravity.BOTTOM));setContentView(frame);window.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE)}
 private fun bottomNav():View{val bar=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;background=card(Color.WHITE)};listOf("HOME","CREDIT","REPAYMENT","DOCUMENTS","MORE").forEach{label->val b=Button(this).apply{text=label;textSize=11f;setAllCaps(false);setOnClickListener{when(label){"HOME"->home();"CREDIT"->startActivity(Intent(this@V5HomeActivity,V5InformalCreditActivity::class.java));"REPAYMENT"->startActivity(Intent(this@V5HomeActivity,V5RepaymentActivity::class.java));"DOCUMENTS"->documents();"MORE"->support("NOTIFICATIONS")}}};bar.addView(b,LinearLayout.LayoutParams(0,dp(64),1f))};return bar}
 private fun header(r:LinearLayout,title:String,sub:String){val h=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(10),dp(12),dp(10));background=card()};h.addView(tv("UDHAARDAAR V5",12f,teal));h.addView(tv(title,23f));h.addView(tv(sub,12f,Color.DKGRAY));r.addView(h);r.addView(Space(this),LinearLayout.LayoutParams(1,dp(8)))}
 override fun onCreate(b:Bundle?){super.onCreate(b);home()};@Suppress("DEPRECATION") override fun onBackPressed(){home()}
 private fun home(){if(!prefs.getBoolean("logged_in",false)){startActivity(Intent(this,LoginActivity::class.java));finish();return};val r=root();header(r,"Financial Command Centre","Guided V5 workflows • clear steps • protected consent checkpoints");val m=prefs.getString("current_mobile","")?:"";put(r,tv("Welcome, ${prefs.getString("name_$m","User")}",19f));put(r,tv("Start with a module below. Each workflow guides you through review → consent → completion.",13f,Color.DKGRAY),58);section(r,"CREDIT & OBLIGATIONS",blue);tile(r,"₹","Register Informal Credit","Personal • business • trade • advance • given/received",blue){startActivity(Intent(this,V5InformalCreditActivity::class.java))};tile(r,"▣","Formal Credit","Bank/NBFC • sanction terms • consent • audit",blue){startActivity(Intent(this,V5FormalCreditActivity::class.java))};tile(r,"↔","Tu Tera, Main Mera (TTMM)","Shared-expense lending • pro-rata split • OTP confirmation",teal){startActivity(Intent(this,V5TTMMActivity::class.java))};tile(r,"⌕","Borrower Profiles","Search • select profile • consent-gated history",teal){startActivity(Intent(this,V5BorrowerActivity::class.java))};tile(r,"✓","Repayment Centre","Payable/receivable • due • partial repayment • OTP",green){startActivity(Intent(this,V5RepaymentActivity::class.java))};tile(r,"▣","Rental / Lease","Agreement capture • OCR • review • consent • lease record",amber){startActivity(Intent(this,V5RentalLeaseActivity::class.java))};section(r,"DOCUMENTS & PROTECTION",amber);tile(r,"▤","DPN + Guarantor Guarantee","Generate • review • OTP consent • version • audit",amber){documents()};tile(r,"▥","Sanction vs Account Charge Check","OCR • review • compare • printable report",amber){startActivity(Intent(this,V5ChargeComparisonActivity::class.java))};tile(r,"♙","Guarantor Profile & Consent","Create/link guarantor • guarantee • OTP consent",red){startActivity(Intent(this,V5GuarantorConsentActivity::class.java))};section(r,"ASSET, SUCCESSION & SUPPORT",teal);tile(r,"₹","Financial / Non-Financial Assets","Assets, evidence, ownership and nominee linkage",teal){startActivity(Intent(this,V5AssetVaultActivity::class.java))};tile(r,"−","Liability Vault","Loans • cards • tax • payables • guarantees",red){startActivity(Intent(this,V5AssetVaultActivity::class.java).putExtra("openCategory","LIABILITY"))};tile(r,"♙","Nominee / Trusted Person","Controlled family access • explicit consent",navy){support("ACCESS")};tile(r,"⌘","Inheritance & Claim Centre","Heir/nominee • evidence • claim lifecycle",red){startActivity(Intent(this,V5DeathClaimLegalActivity::class.java))};tile(r,"⚖","Legal Assistance","Evidence bundles • case tracking",red){support("LEGAL")};tile(r,"▤","Notifications & Readiness","Due dates • renewals • maturity • claim tasks",green){support("NOTIFICATIONS")};put(r,Button(this).apply{text="MY PROFILE / PARTY DIRECTORY";setOnClickListener{startActivity(Intent(this@V5HomeActivity,V5BorrowerActivity::class.java))}},50);put(r,Button(this).apply{text="LOGOUT";setOnClickListener{prefs.edit().putBoolean("logged_in",false).remove("current_mobile").apply();startActivity(Intent(this@V5HomeActivity,LoginActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP));finish()}},50);show(r)}
 private fun section(r:LinearLayout,s:String,c:Int){r.addView(tv(s,12f,c))};private fun tile(r:LinearLayout,icon:String,title:String,sub:String,c:Int,fn:()->Unit){val x=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(10),dp(7),dp(8),dp(7));background=card();setOnClickListener{fn()}};x.addView(tv(icon,22f,c),LinearLayout.LayoutParams(dp(42),dp(52)));val z=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;layoutParams=LinearLayout.LayoutParams(0,-2,1f)};z.addView(tv(title,16f));z.addView(tv(sub,11f,Color.DKGRAY));x.addView(z);x.addView(tv("›",26f,c));r.addView(x);r.addView(Space(this),LinearLayout.LayoutParams(1,dp(5)))}
 private fun support(mode:String){startActivity(Intent(this,V5SupportWorkflowsActivity::class.java).putExtra("mode",mode))}
 private fun documents(){val r=root();header(r,"Digital Documents & Consent","Review first • explicit OTP consent • timestamped archive");put(r,tv("Required order: terms → document draft → review → consent → OTP verification → registration → archive.",14f),92);put(r,Button(this).apply{text="GENERATE / REVIEW DOCUMENT PACKET";setOnClickListener{val id="DOC-${System.currentTimeMillis()}";V5LocalStore(this@V5HomeActivity).add("documents",org.json.JSONObject().apply{put("id",id);put("type","DPN_GUARANTEE_PACKET");put("status","DRAFT");put("version",1);put("createdAt",System.currentTimeMillis())});AlertDialog.Builder(this@V5HomeActivity).setTitle("Document packet created").setMessage("Draft packet $id is versioned and timestamped. Review and consent are required before protected credit registration.").setPositiveButton("OK",null).show()}},58);put(r,Button(this).apply{text="OPEN GUARANTOR CONSENT WORKFLOW";setOnClickListener{startActivity(Intent(this@V5HomeActivity,V5GuarantorConsentActivity::class.java))}},58);put(r,Button(this).apply{text="BACK TO HOME";setOnClickListener{home()}},50);show(r)}
}
